import {Column, Generated, PrimaryColumn} from 'typeorm';
import {numberTransformer} from '../transformers/number.transformer';

/**
 * Columns inherited by every table (7.2).
 *
 * `id` is internal and never exposed by the API; `publicId` is the only
 * identifier the client knows. The UUID is generated by the application before
 * insert (`BaseEntitySubscriber`), never by MySQL (D28).
 */
export abstract class BaseEntity {
  @PrimaryColumn({type: 'bigint', unsigned: true, transformer: numberTransformer})
  @Generated('increment')
  id!: number;

  @Column({
    type: 'char',
    length: 36,
    charset: 'ascii',
    collation: 'ascii_bin',
  })
  publicId!: string;
}
